SELECT umr.create_time AS createTime, umr.amount AS amount, umr.`balance_after` - umr.`balance_before` AS money, umr.`ext_money_after` - umr.`ext_money_before` AS awards, umr.`balance_before` AS balanceBefore, umr.`ext_money_before` AS extMoneyBefore, umr.`pay_code` AS payCode, umr.type AS TYPE, umr.remark AS remark, ba.addr_name AS addrName FROM fund_transaction umr LEFT JOIN bluetooth_address ba ON umr.address_id = ba.id WHERE umr.user_id = #{userId} AND umr.type IN
#{type}
ORDER BY umr.create_time DESC LIMIT #{limit} OFFSET #{offset}

